import re


def _class(pattern, start):
    i = start + 1
    negated = i < len(pattern) and pattern[i] == "!"
    if negated:
        i += 1
    chars = []
    if i < len(pattern) and pattern[i] == "]":
        chars.append("]")
        i += 1
    while i < len(pattern) and pattern[i] != "]":
        chars.append(pattern[i])
        i += 1
    if i >= len(pattern):
        raise ValueError("unclosed character class")
    body = []
    j = 0
    while j < len(chars):
        if j + 2 < len(chars) and chars[j + 1] == "-":
            if ord(chars[j + 2]) < ord(chars[j]):
                raise ValueError("reversed character range")
            body.append(re.escape(chars[j]) + "-" + re.escape(chars[j + 2]))
            j += 3
        else:
            body.append(re.escape(chars[j]))
            j += 1
    return "(?:(?!/)[" + ("^" if negated else "") + "".join(body) + "])" , i + 1


def _segment_regex(segment):
    out, i = [], 0
    while i < len(segment):
        ch = segment[i]
        if ch == "\\":
            if i + 1 == len(segment):
                raise ValueError("trailing escape")
            out.append(re.escape(segment[i + 1]))
            i += 2
        elif ch == "*":
            out.append("[^/]*")
            i += 1
        elif ch == "?":
            out.append("[^/]")
            i += 1
        elif ch == "[":
            piece, i = _class(segment, i)
            out.append(piece)
        else:
            out.append(re.escape(ch))
            i += 1
    return "".join(out)


def matches(pattern, path):
    """True when the whole path matches the glob pattern. See TASK.md."""
    segments, current, i = [], [], 0
    while i < len(pattern):
        if pattern[i] == "\\":
            if i + 1 == len(pattern):
                raise ValueError("trailing escape")
            current.extend(pattern[i:i + 2])
            i += 2
        elif pattern[i] == "/":
            segments.append("".join(current))
            current, i = [], i + 1
        else:
            current.append(pattern[i])
            i += 1
    segments.append("".join(current))
    if pattern == "**":
        return True
    regex = []
    for index, segment in enumerate(segments):
        if segment == "**" and len(segments) > 1:
            if index == 0:
                regex.append("(?:[^/]+/)*")
            elif index == len(segments) - 1:
                regex.append("(?:/[^/]+)*")
            else:
                regex.append("/(?:[^/]+/)*")
        else:
            if index and segments[index - 1] != "**":
                regex.append("/")
            regex.append(_segment_regex(segment))
    return re.fullmatch("".join(regex), path) is not None
